import{_ as a,o as d,c as e,a4 as r}from"./chunks/framework.vNSRaLQv.js";const m=JSON.parse('{"title":"开发工具链整理方案","description":"","frontmatter":{"title":"开发工具链整理方案","date":"2026-06-25T00:00:00.000Z"},"headers":[],"relativePath":"posts/开发工具链整理方案.md","filePath":"posts/开发工具链整理方案.md"}'),l={name:"posts/开发工具链整理方案.md"};function i(n,t,s,o,h,p){return d(),e("div",null,[...t[0]||(t[0]=[r(`<p># 开发工具链 &amp; SDK 全面审计 + 整理方案</p><blockquote><p>扫描时间: 2026-06-25 目标: 消除重复，统一归档到 D 盘，规划环境变量迁移</p></blockquote><hr><h2 id="一、当前全量清单-32-项" tabindex="-1">一、当前全量清单（32 项） <a class="header-anchor" href="#一、当前全量清单-32-项" aria-label="Permalink to &quot;一、当前全量清单（32 项）&quot;">​</a></h2><h3 id="编程语言-运行时" tabindex="-1">编程语言 &amp; 运行时 <a class="header-anchor" href="#编程语言-运行时" aria-label="Permalink to &quot;编程语言 &amp; 运行时&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>当前路径</th><th>版本</th><th>状态</th></tr></thead><tbody><tr><td>Node.js (nvm)</td><td>D:\\Program Files (x86)\\nvm\\ → symlink D:\\Program Files (x86)\\nodejs</td><td>v22.22.2</td><td>⚠ PATH有冗余</td></tr><tr><td>Python</td><td>C:\\Users\\a1\\AppData\\Local\\Programs\\Python\\Python312\\</td><td>3.12.10</td><td>⚠ 在C盘</td></tr><tr><td>uv (Python工具)</td><td>D:\\uv\\bin</td><td>latest</td><td>正常</td></tr><tr><td>Go</td><td>D:\\Program Files\\Go</td><td>1.24.1</td><td>正常</td></tr><tr><td>Java (Corretto JDK)</td><td>D:\\Program Files (x86)\\corretto-17</td><td>17.0.16</td><td>正常</td></tr><tr><td>Rust</td><td>D:\\tools\\rust</td><td>未知</td><td>❌ 安装损坏，不在PATH</td></tr></tbody></table><h3 id="c-c-编译器-重复" tabindex="-1">C/C++ 编译器（重复！） <a class="header-anchor" href="#c-c-编译器-重复" aria-label="Permalink to &quot;C/C++ 编译器（重复！）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>当前路径</th><th>版本</th><th>状态</th></tr></thead><tbody><tr><td>MinGW64 (独立安装)</td><td>D:\\Program Files (x86)\\mingw64</td><td>g++ 14.2.0</td><td>⚠ 重复</td></tr><tr><td>MSYS2/MinGW64</td><td>C:\\msys64\\mingw64</td><td>g++ 16.1.0</td><td>⚠ 重复 + 在C盘</td></tr></tbody></table><h3 id="构建工具-包管理" tabindex="-1">构建工具 &amp; 包管理 <a class="header-anchor" href="#构建工具-包管理" aria-label="Permalink to &quot;构建工具 &amp; 包管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>当前路径</th><th>状态</th></tr></thead><tbody><tr><td>CMake</td><td>C:\\Program Files\\CMake</td><td>⚠ 在C盘</td></tr><tr><td>Maven</td><td>D:\\apache-maven-3.9.5</td><td>⚠ 散落在D盘根目录</td></tr><tr><td>vcpkg</td><td>D:\\tools\\vcpkg</td><td>❌ 未引导，空壳</td></tr><tr><td>VS Build Tools</td><td>D:\\tools\\vs_buildtools.exe</td><td>❌ 只有安装器，未安装</td></tr></tbody></table><h3 id="数据库-缓存" tabindex="-1">数据库 &amp; 缓存 <a class="header-anchor" href="#数据库-缓存" aria-label="Permalink to &quot;数据库 &amp; 缓存&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>当前路径</th><th>版本</th><th>状态</th></tr></thead><tbody><tr><td>Redis</td><td>D:\\Program Files\\Redis-x64-3.2.100</td><td>3.2.100</td><td>⚠ 极旧版本</td></tr><tr><td>MySQL</td><td>D:\\MySQL\\MySQL Server 5.7</td><td>5.7</td><td>⚠ 散落D盘根</td></tr><tr><td>MongoDB Shell</td><td>D:\\Program Files\\mongosh-2.7.0-win32-x64</td><td>2.7.0</td><td>正常</td></tr></tbody></table><h3 id="android-移动" tabindex="-1">Android &amp; 移动 <a class="header-anchor" href="#android-移动" aria-label="Permalink to &quot;Android &amp; 移动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>当前路径</th><th>状态</th></tr></thead><tbody><tr><td>Android SDK</td><td>D:\\Android\\Sdk</td><td>正常</td></tr><tr><td>scrcpy</td><td>D:\\Program Files (x86)\\scrcpy-win64-v3.3.1</td><td>⚠ 自带adb抢先于SDK的adb</td></tr></tbody></table><h3 id="多媒体-ai" tabindex="-1">多媒体 &amp; AI <a class="header-anchor" href="#多媒体-ai" aria-label="Permalink to &quot;多媒体 &amp; AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>当前路径</th><th>状态</th></tr></thead><tbody><tr><td>ffmpeg</td><td>D:\\Program Files\\ffmpeg</td><td>正常</td></tr><tr><td>whisper</td><td>D:\\Program Files\\whisper-bin-x64</td><td>正常</td></tr><tr><td>Graphviz</td><td>D:\\Program Files\\Graphviz</td><td>正常</td></tr></tbody></table><h3 id="网络-调试" tabindex="-1">网络 &amp; 调试 <a class="header-anchor" href="#网络-调试" aria-label="Permalink to &quot;网络 &amp; 调试&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>当前路径</th><th>状态</th></tr></thead><tbody><tr><td>Docker</td><td>C:\\Program Files\\Docker</td><td>⚠ 在C盘</td></tr><tr><td>Fiddler</td><td>D:\\Program Files\\Fiddler</td><td>正常</td></tr><tr><td>Sunshine</td><td>D:\\Program Files\\Sunshine</td><td>正常（非开发工具）</td></tr></tbody></table><h3 id="远程-终端" tabindex="-1">远程 &amp; 终端 <a class="header-anchor" href="#远程-终端" aria-label="Permalink to &quot;远程 &amp; 终端&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>当前路径</th><th>状态</th></tr></thead><tbody><tr><td>Git</td><td>D:\\Program Files\\Git</td><td>正常</td></tr><tr><td>GitHub CLI</td><td>C:\\Program Files\\GitHub CLI</td><td>⚠ 在C盘</td></tr><tr><td>Xshell 8</td><td>D:\\Program Files\\Xshell 8</td><td>正常</td></tr><tr><td>SecureCRT</td><td>D:\\Program Files (x86)\\SecureCRT 9.2</td><td>⚠ 与Xshell功能重复</td></tr></tbody></table><h3 id="ide-编辑器" tabindex="-1">IDE &amp; 编辑器 <a class="header-anchor" href="#ide-编辑器" aria-label="Permalink to &quot;IDE &amp; 编辑器&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>当前路径</th><th>状态</th></tr></thead><tbody><tr><td>VS Code</td><td>D:\\Microsoft VS Code</td><td>正常</td></tr><tr><td>Cursor</td><td>D:\\Program Files (x86)\\cursor</td><td>正常</td></tr><tr><td>Trae CN</td><td>D:\\Program Files (x86)\\Trae CN</td><td>正常</td></tr></tbody></table><h3 id="消息队列" tabindex="-1">消息队列 <a class="header-anchor" href="#消息队列" aria-label="Permalink to &quot;消息队列&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>当前路径</th><th>状态</th></tr></thead><tbody><tr><td>RocketMQ</td><td>D:\\rocketmq-all-5.3.0-bin-release</td><td>⚠ 散落D盘根</td></tr></tbody></table><h3 id="npm-全局包" tabindex="-1">npm 全局包 <a class="header-anchor" href="#npm-全局包" aria-label="Permalink to &quot;npm 全局包&quot;">​</a></h3><h2 id="codex-claude-gemini-opencode-pnpm-yarn-code-server-n8n-plantuml-mcp-server" tabindex="-1">codex, claude, gemini, opencode, pnpm, yarn, code-server, n8n, plantuml-mcp-server <a class="header-anchor" href="#codex-claude-gemini-opencode-pnpm-yarn-code-server-n8n-plantuml-mcp-server" aria-label="Permalink to &quot;codex, claude, gemini, opencode, pnpm, yarn, code-server, n8n, plantuml-mcp-server&quot;">​</a></h2><h2 id="二、发现的问题" tabindex="-1">二、发现的问题 <a class="header-anchor" href="#二、发现的问题" aria-label="Permalink to &quot;二、发现的问题&quot;">​</a></h2><h3 id="问题1-path-严重重复" tabindex="-1">问题1: PATH 严重重复 <a class="header-anchor" href="#问题1-path-严重重复" aria-label="Permalink to &quot;问题1: PATH 严重重复&quot;">​</a></h3><p>几乎所有用户级 PATH 条目都出现了 2~3 次，共 30+ 重复项。包括 nodejs 出现 3 次，nvm 出现 3 次。</p><h3 id="问题2-nvm-nodejs-路径冗余" tabindex="-1">问题2: nvm + nodejs 路径冗余 <a class="header-anchor" href="#问题2-nvm-nodejs-路径冗余" aria-label="Permalink to &quot;问题2: nvm + nodejs 路径冗余&quot;">​</a></h3><p>nvm 管理 node 版本，symlink D:\\Program Files (x86)\\nodejs → D:\\Program Files (x86)\\nvm\\v22.22.2。但 PATH 中两个路径都存在，只需 symlink 路径即可。</p><h3 id="问题3-两套-gcc-编译器" tabindex="-1">问题3: 两套 GCC 编译器 <a class="header-anchor" href="#问题3-两套-gcc-编译器" aria-label="Permalink to &quot;问题3: 两套 GCC 编译器&quot;">​</a></h3><ul><li>D:\\Program Files (x86)\\mingw64 → g++ 14.2.0 (MinGW-Builds)</li><li>C:\\msys64\\mingw64 → g++ 16.1.0 (MSYS2) 功能完全重复，且 MSYS2 还自带 make 等工具更完整。</li></ul><h3 id="问题4-adb-路径冲突" tabindex="-1">问题4: adb 路径冲突 <a class="header-anchor" href="#问题4-adb-路径冲突" aria-label="Permalink to &quot;问题4: adb 路径冲突&quot;">​</a></h3><p>scrcpy 自带的 adb.exe 在 PATH 中优先于 Android SDK 的 adb。当前 adb 命令指向 scrcpy 目录。</p><h3 id="问题5-c-盘残留工具" tabindex="-1">问题5: C 盘残留工具 <a class="header-anchor" href="#问题5-c-盘残留工具" aria-label="Permalink to &quot;问题5: C 盘残留工具&quot;">​</a></h3><p>Python, CMake, Docker, GitHub CLI, MSYS2 都在 C 盘，不符合&quot;D盘集中&quot;原则。</p><h3 id="问题6-rust-安装损坏" tabindex="-1">问题6: Rust 安装损坏 <a class="header-anchor" href="#问题6-rust-安装损坏" aria-label="Permalink to &quot;问题6: Rust 安装损坏&quot;">​</a></h3><p>D:\\tools\\rust 有 cargo/rustup 目录但不在 PATH 中，安装不完整。</p><h3 id="问题7-散落的工具目录" tabindex="-1">问题7: 散落的工具目录 <a class="header-anchor" href="#问题7-散落的工具目录" aria-label="Permalink to &quot;问题7: 散落的工具目录&quot;">​</a></h3><h2 id="maven-mysql-rocketmq-直接散落在-d-盘根目录-没有统一管理。" tabindex="-1">Maven, MySQL, RocketMQ 直接散落在 D 盘根目录，没有统一管理。 <a class="header-anchor" href="#maven-mysql-rocketmq-直接散落在-d-盘根目录-没有统一管理。" aria-label="Permalink to &quot;Maven, MySQL, RocketMQ 直接散落在 D 盘根目录，没有统一管理。&quot;">​</a></h2><h2 id="三、整理方案" tabindex="-1">三、整理方案 <a class="header-anchor" href="#三、整理方案" aria-label="Permalink to &quot;三、整理方案&quot;">​</a></h2><h3 id="方案-统一到-d-dev-目录-参考结构" tabindex="-1">方案: 统一到 D:\\dev 目录（参考结构） <a class="header-anchor" href="#方案-统一到-d-dev-目录-参考结构" aria-label="Permalink to &quot;方案: 统一到 D:\\dev 目录（参考结构）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>D:\\dev\\</span></span>
<span class="line"><span>├── python\\        ← 从C盘迁移 Python 3.12</span></span>
<span class="line"><span>├── go\\            ← 从 D:\\Program Files\\Go 迁移</span></span>
<span class="line"><span>├── java\\          ← Corretto JDK 17</span></span>
<span class="line"><span>├── rust\\          ← 重新安装 Rust</span></span>
<span class="line"><span>├── mingw64\\       ← 保留 MSYS2 (C:\\msys64\\mingw64 不动，软链接)</span></span>
<span class="line"><span>├── cmake\\         ← 从C盘迁移</span></span>
<span class="line"><span>├── maven\\         ← 从 D:\\apache-maven-3.9.5 迁移</span></span>
<span class="line"><span>├── ffmpeg\\        ← 从 D:\\Program Files\\ffmpeg 迁移</span></span>
<span class="line"><span>├── android-sdk\\   ← 从 D:\\Android\\Sdk 迁移</span></span>
<span class="line"><span>├── git\\           ← 保持 D:\\Program Files\\Git 不动</span></span>
<span class="line"><span>├── tools\\         ← 保留 D:\\tools (openssl-src, vcpkg)</span></span>
<span class="line"><span>├── databases\\</span></span>
<span class="line"><span>│   ├── redis\\     ← 从 D:\\Program Files\\Redis-x64-3.2.100 迁移</span></span>
<span class="line"><span>│   ├── mysql\\     ← 从 D:\\MySQL\\MySQL Server 5.7 迁移</span></span>
<span class="line"><span>│   └── mongosh\\   ← 从 D:\\Program Files\\mongosh 迁移</span></span>
<span class="line"><span>└── docker\\        ← Docker 从C盘迁移较复杂，建议单独处理</span></span></code></pre></div><h3 id="⚠-但是-直接迁移风险很大" tabindex="-1">⚠ 但是，直接迁移风险很大 <a class="header-anchor" href="#⚠-但是-直接迁移风险很大" aria-label="Permalink to &quot;⚠ 但是，直接迁移风险很大&quot;">​</a></h3><ol><li>很多工具安装时写入了注册表、服务、内部路径，单纯移动文件夹会导致无法使用</li><li>MySQL, Redis, Docker 是注册为 Windows 服务的，迁移需要卸载再重装</li><li>nvm 的 symlink 和 settings.txt 需要一起改</li><li>当前这些工具都能正常工作</li></ol><h3 id="推荐方案-先修-path-清理重复-以后新工具统一装-d-dev" tabindex="-1">推荐方案: 先修 PATH + 清理重复，以后新工具统一装 D:\\dev <a class="header-anchor" href="#推荐方案-先修-path-清理重复-以后新工具统一装-d-dev" aria-label="Permalink to &quot;推荐方案: 先修 PATH + 清理重复，以后新工具统一装 D:\\dev&quot;">​</a></h3><p><strong>第一步: 清理 PATH（安全，立刻见效）</strong></p><ul><li>删除所有重复的 PATH 条目（30+ 个 → 降到 0 个重复）</li><li>删除多余的 D:\\Program Files (x86)\\nvm 条目（保留 symlink 路径即可）</li><li>确保 Android SDK adb 在 scrcpy 之前（或统一用 SDK 的 adb） <strong>第二步: 清理损坏项</strong></li><li>删除 D:\\tools\\rust（损坏的 Rust 安装）</li><li>删除 D:\\tools\\vcpkg（未引导的空壳）-- 除非你确实打算用 vcpkg</li><li>决定保留哪个 GCC: 建议只保留 MSYS2 (C:\\msys64，版本更新)，删除独立 MinGW <strong>第三步: C盘工具处理</strong></li><li>Python: 迁移到 D 盘需要重装（推荐 D:\\dev\\python），pip 包需要重装</li><li>CMake: 可以直接移动文件夹 + 更新 PATH</li><li>Docker: 绑定 WSL2，不建议动</li><li>GitHub CLI: 可以直接移动 + 更新 PATH <strong>第四步: 新工具统一规范</strong></li><li>以后所有新开发工具统一安装到 D:\\dev&lt;tool-name&gt;\\</li><li>新工具的 PATH 条目只加一次 <strong>第五步: 环境变量迁移</strong></li><li>清理后 PATH 条目数可以减半</li><li>提供 PATH-MIGRATION.txt 记录变更前后对比，方便回滚</li></ul><hr><h2 id="四、需要你决定的事" tabindex="-1">四、需要你决定的事 <a class="header-anchor" href="#四、需要你决定的事" aria-label="Permalink to &quot;四、需要你决定的事&quot;">​</a></h2><ol><li>Python 要不要迁移到 D 盘？ 需要重装，pip 包要重装</li><li>Rust 还需不需要？ 如果不需要 Moonlight 编译了，可以不装</li><li>vcpkg 还需不需要？ 未引导的空壳，如果不需要可以删</li><li>两套 MinGW 保留哪个？ 建议保留 MSYS2 (新版本 + 完整工具链)</li><li>Maven 还需要吗？ 如果不做 Java 项目可以不装</li><li>RocketMQ 还需要吗？ 如果不用可以删</li><li>Docker 要不要动？ 强烈建议不动，绑WSL2太深</li><li>先只做 PATH 清理 + 重复项清理？ 还是要全面搬迁？</li></ol><hr><h2 id="五、执行顺序建议" tabindex="-1">五、执行顺序建议 <a class="header-anchor" href="#五、执行顺序建议" aria-label="Permalink to &quot;五、执行顺序建议&quot;">​</a></h2><p>如果确认方案，执行顺序:</p><ol><li>备份当前 PATH（导出注册表或截图）</li><li>清理 PATH 重复项（最安全的第一步）</li><li>处理 Rust 残留 / vcpkg 空壳</li><li>决定 GCC 选哪个</li><li>处理 C 盘工具（CMake, GitHub CLI 可直接移; Python/Docker 需要重装）</li><li>散落目录归档（Maven, MySQL, RocketMQ）</li><li>新建 D:\\dev 规范，写入 README</li></ol>`,56)])])}const b=a(l,[["render",i]]);export{m as __pageData,b as default};
